// 40x40 RGBA icon artwork downsampled from the approved OSTen icon set.
// Folder: Option B; Finder: Option C; System: Option B.
// Base64 encodes one 96-color RGBA palette and 1600 indexed pixels per icon.
#ifndef OSTEN_ICON_ARTWORK_H
#define OSTEN_ICON_ARTWORK_H

struct OSTenArtwork {
    const char* palette;
    const char* pixels;
};

static const int kOSTenArtworkSize = 40;
static const int kOSTenArtworkColors = 96;
static const OSTenArtwork kOSTenArtwork[] = {
    { "",
      "" },
    { "",
      "" },
    { "",
      "" }
};

#endif // OSTEN_ICON_ARTWORK_H
